templates.settingsGradle:
pluginManagement {
	repositories {
		maven {
			name = 'Fabric'
			url = 'https://maven.fabricmc.net/'
		}
		mavenCentral()
		gradlePluginPortal()
	}
}

rootProject.name = '{{modId}}'

templates.buildGradle:
plugins {
	id 'net.fabricmc.fabric-loom-remap' version "${loom_version}"
	id 'maven-publish'
}

version = project.mod_version
group = project.maven_group

base {
	archivesName = project.archives_base_name
}

repositories {
}

dependencies {
	minecraft "com.mojang:minecraft:${project.minecraft_version}"
	mappings loom.officialMojangMappings()
	modImplementation "net.fabricmc:fabric-loader:${project.loader_version}"
	modImplementation "net.fabricmc.fabric-api:fabric-api:${project.fabric_api_version}"
}

processResources {
	inputs.property "version", project.version
	filesMatching("fabric.mod.json") {
		expand "version": project.version
	}
}

tasks.withType(JavaCompile).configureEach {
	it.options.release = {{javaVersion}}
}

java {
	withSourcesJar()
	sourceCompatibility = JavaVersion.VERSION_{{javaVersion}}
	targetCompatibility = JavaVersion.VERSION_{{javaVersion}}
}

templates.gradleProps:
# Gradle
org.gradle.jvmargs=-Xmx1G
org.gradle.parallel=true
org.gradle.configuration-cache=false

# Fabric properties (check https://fabricmc.net/develop)
minecraft_version={{mcVersion}}
loader_version={{loaderVersion}}
loom_version={{gradle_loomVersion}}
fabric_api_version={{gradle_fabricApiVersion}}

# Mod properties
mod_version={{modVersion}}
maven_group={{packageName}}
archives_base_name={{modId}}

